CREATE TABLE `audit_logs` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`action` VARCHAR(120) NOT NULL,`resource_type` VARCHAR(80) NOT NULL,`resource_id` VARCHAR(180) NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`metadata_json` JSON NOT NULL,`occurred_at` DATETIME(3) NOT NULL,`schema_version` INT UNSIGNED NOT NULL,PRIMARY KEY (`id`),KEY `idx_audit_scope_time` (`organization_id`,`workspace_id`,`occurred_at`),KEY `idx_audit_resource_time` (`organization_id`,`resource_type`,`resource_id`,`occurred_at`),KEY `idx_audit_trace` (`trace_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
